[41.391472,-1.579045],[41.39141,-1.579189],[41.39134,-1.579329],[41.391253,-1.579493],[41.391185,-1.579652],[41.391116,-1.579782],[41.391095,-1.579906],[41.391019,-1.580023],[41.390943,-1.58014],[41.390839,-1.580287],[41.390761,-1.580411],[41.390659,-1.580512],[41.390584,-1.580699],[41.390519,-1.580815],[41.390387,-1.581011],[41.390349,-1.581132],[41.390272,-1.581282],[41.390188,-1.581418],[41.390117,-1.581573],[41.390063,-1.581749],[41.389951,-1.581842],[41.389863,-1.581902],[41.389778,-1.58199],[41.389661,-1.582062],[41.389567,-1.582105],[41.389449,-1.582185],[41.389326,-1.582143],[41.389195,-1.582202],[41.389069,-1.582171],[41.388887,-1.582171],[41.388747,-1.582242],[41.38869,-1.582417],[41.388722,-1.582546],[41.388781,-1.582687],[41.38878,-1.582891],[41.388679,-1.582929],[41.388574,-1.583047],[41.388485,-1.583192],[41.388281,-1.583203],[41.388154,-1.583261],[41.388025,-1.583351],[41.38795,-1.583493],[41.387876,-1.583636],[41.387798,-1.58381],[41.387721,-1.583985],[41.387588,-1.584093],[41.387455,-1.584201],[41.387392,-1.584324],[41.387328,-1.584448],[41.387265,-1.584592],[41.387204,-1.584725],[41.387189,-1.584887],[41.387126,-1.585057],[41.387094,-1.585223],[41.387063,-1.585412],[41.387006,-1.585636],[41.386948,-1.58586],[41.386952,-1.586058],[41.386942,-1.58624],[41.38697,-1.586378],[41.386951,-1.586588],[41.386932,-1.58676],[41.386893,-1.586905],[41.386833,-1.587062],[41.386771,-1.587204],[41.386722,-1.587384],[41.386664,-1.587504],[41.386561,-1.58767],[41.386464,-1.587775],[41.386381,-1.587856],[41.386302,-1.587973],[41.386192,-1.588111],[41.386065,-1.588245],[41.385961,-1.588345],[41.385869,-1.588465],[41.385764,-1.5886],[41.38566,-1.588735],[41.385582,-1.588869],[41.385549,-1.589058],[41.385514,-1.589253],[41.385452,-1.589449],[41.385385,-1.589661],[41.385252,-1.589771],[41.38518,-1.589892],[41.385142,-1.590021],[41.385133,-1.59015],[41.38511,-1.590298],[41.385121,-1.590488],[41.38509,-1.590731],[41.385056,-1.59087],[41.384979,-1.591033],[41.38487,-1.591231],[41.384736,-1.591377],[41.384582,-1.591432],[41.384428,-1.591412],[41.38433,-1.591317],[41.384232,-1.591221],[41.384108,-1.591067],[41.383984,-1.590912],[41.383901,-1.590814],[41.383817,-1.590735],[41.383715,-1.590632],[41.383625,-1.590587],[41.383525,-1.59056],[41.383386,-1.590649],[41.383284,-1.590823],[41.383282,-1.590825],[41.383179,-1.591001],[41.383059,-1.59118],[41.383027,-1.591342],[41.382995,-1.591505],[41.382879,-1.591717],[41.38272,-1.591729],[41.382561,-1.591742],[41.382402,-1.591754]]'::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_km double precision;
  v_gap double precision;
  v_center double precision;
  v_closure double precision;
  v_invalid integer;
begin
  select h.id,h.latitude,h.longitude,h.distance_km,t.status
    into v_route from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
  where h.id='osm-relation-5462942'
    and h.source='openstreetmap'
    and h.name='De Huérmeda al mirador de la Cocha'
    and h.route_ref='SL-Z 41'
    and h.official_url='https://www.caminosnaturales.com/'
    and exists(select 1 from public.hiking_route_regions m
      where m.route_id=h.id and m.published);
  if not found then
    -- Idempotent on an already curated record with the corrected source URL.
    if exists(select 1 from public.hiking_route_tracks t
      join public.hiking_routes h on h.id=t.route_id
      where h.id='osm-relation-5462942' and t.status='ready'
        and h.official_url='https://www.senderosfam.es/ruta/ficha/874/') then
      return;
    end if;
    raise exception 'FAM SL-Z 41 identity or region changed';
  end if;
  if v_route.status='ready' then return; end if;
  with p as (
    select ordinality n,(point->>0)::float8 lat,(point->>1)::float8 lon
    from jsonb_array_elements(v_coords) with ordinality as x(point,ordinality)
  ), s as (
    select *,lag(lat) over(order by n) pl,lag(lon) over(order by n) po from p
  ), d as (
    select case when pl is null then 0 else
      6371*2*asin(sqrt(least(1,power(sin(radians(lat-pl)/2),2)
        +cos(radians(pl))*cos(radians(lat))
        *power(sin(radians(lon-po)/2),2)))) end step_km,
      6371*2*asin(sqrt(least(1,power(sin(radians(lat-v_route.latitude)/2),2)
        +cos(radians(v_route.latitude))*cos(radians(lat))
        *power(sin(radians(lon-v_route.longitude)/2),2)))) center_km,
      (lat between 40 and 43 and lon between -3 and 0) valid from s
  ) select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_km,v_gap,v_center,v_invalid from d;
  select 6371*2*asin(sqrt(least(1,
    power(sin(radians(((v_coords->0->>0)::float8-
      (v_coords->(v_count-1)->>0)::float8)/2)),2)
    +cos(radians((v_coords->0->>0)::float8))
      *cos(radians((v_coords->(v_count-1)->>0)::float8))
      *power(sin(radians(((v_coords->0->>1)::float8-
        (v_coords->(v_count-1)->>1)::float8)/2)),2))))
    into v_closure;
  if v_count<>757 or v_invalid>0
    or v_route.distance_km is not null
    or abs(v_km/12.3-1)>0.05
    or v_gap>0.05 or v_center>0.50 or v_closure>0.30
  then raise exception
    'FAM SL-Z 41 failed: points %, km %, gap %, center %, closure %, invalid %',
    v_count,v_km,v_gap,v_center,v_closure,v_invalid;
  end if;
  select jsonb_agg(jsonb_build_object('lat',(point->>0)::float8,
    'lon',(point->>1)::float8) order by ordinality) into v_points
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality);
  insert into public.hiking_route_tracks
    (route_id,status,segments,checked_at,continuity_checked,
     geometry_source,geometry_source_url,official)
  values ('osm-relation-5462942','ready',jsonb_build_array(v_points),
    now(),true,'Federación Aragonesa de Montañismo',
    'https://www.senderosfam.es/visorprames/get_route_GPX.php?id=874',true)
  on conflict(route_id) do update set
    status=excluded.status,segments=excluded.segments,checked_at=excluded.checked_at,
    continuity_checked=true,geometry_source=excluded.geometry_source,
    geometry_source_url=excluded.geometry_source_url,official=true;
  update public.hiking_routes
    set trace_available=true,published=true,distance_km=12.3,
      route_type=coalesce(route_type,'Circular'),
      official_url='https://www.senderosfam.es/ruta/ficha/874/'
    where id='osm-relation-5462942';
end
$curate$;
